CREATE SCHEMA IF NOT EXISTS nicsi_erp;
SET search_path = nicsi_erp;

-- Clean up any conflicting views in nicsi_erp before creating tables
DROP VIEW IF EXISTS nicsi_erp.app_user CASCADE;
DROP VIEW IF EXISTS nicsi_erp.project_manager CASCADE;
DROP VIEW IF EXISTS nicsi_erp.project_list CASCADE;
DROP VIEW IF EXISTS nicsi_erp.purchase_order_list CASCADE;
DROP VIEW IF EXISTS nicsi_erp.tax_invoice_list CASCADE;
DROP VIEW IF EXISTS nicsi_erp.bill_desk_list CASCADE;
DROP VIEW IF EXISTS nicsi_erp.project_type_summary CASCADE;
DROP VIEW IF EXISTS nicsi_erp.invoice_list CASCADE;
DROP VIEW IF EXISTS nicsi_erp.customer_master_list CASCADE;

DROP VIEW IF EXISTS nicsi_erp.project_list CASCADE;
CREATE TABLE IF NOT EXISTS nicsi_erp.project_list (
    header_id BIGINT PRIMARY KEY,
    project_id BIGINT,
    prj_mgr_id BIGINT,
    project_cd TEXT,
    prj_nm TEXT,
    customer_name TEXT,
    prj_budget_no NUMERIC(20,2),
    amount_received NUMERIC(20,2),
    no_of_po BIGINT,
    po_amount NUMERIC(20,2),
    no_of_inv_billdesk BIGINT,
    no_of_exp_invocie BIGINT,
    total_invoice_amount BIGINT,
    total_amount_paid BIGINT,
    no_of_tax_invoice BIGINT,
    total_tax_invocie_amount NUMERIC(20,2),
    project_abp NUMERIC(20,2),
    created_on DATE,
    cust_id BIGINT,
    prj_type TEXT,
    user_email TEXT,
    mobile_number NUMERIC(20,2),
    hod_email TEXT,
    nic_cord_emailid TEXT,
    staff_email_id TEXT,
    total_penalty_amt NUMERIC(20,2),
    ministry TEXT,
    department TEXT,
    project_category TEXT,
    state_code TEXT,
    nicsi_commission NUMERIC(20,2) GENERATED ALWAYS AS (GREATEST(0, amount_received - (po_amount - total_penalty_amt))) STORED
);

ON CONFLICT (header_id) DO NOTHING;

DROP VIEW IF EXISTS nicsi_erp.purchase_order_list CASCADE;
CREATE TABLE IF NOT EXISTS nicsi_erp.purchase_order_list (
    header_id BIGINT PRIMARY KEY,
    project_id BIGINT,
    project_no TEXT,
    prj_mgr_id BIGINT,
    vendor_id BIGINT,
    vendor_name TEXT,
    final_po_no TEXT,
    po_date DATE,
    frdate DATE,
    todate DATE,
    total NUMERIC(20,2),
    approval_status TEXT,
    created_date DATE
);

ON CONFLICT (header_id) DO NOTHING;

DROP VIEW IF EXISTS nicsi_erp.tax_invoice_list CASCADE;
CREATE TABLE IF NOT EXISTS nicsi_erp.tax_invoice_list (
    header_id BIGINT PRIMARY KEY,
    project_id BIGINT,
    prj_mgr_id BIGINT,
    cust_id BIGINT,
    cust_gstin_no TEXT,
    prj_gstn_no TEXT,
    project_no TEXT,
    po_no TEXT,
    ampono NUMERIC(20,2),
    user_bill_no TEXT,
    bill_date DATE,
    bill_status TEXT,
    billing_period_from TEXT,
    billing_period_to TEXT,
    supp_inv_num BIGINT,
    totalamount BIGINT,
    bill_type TEXT,
    state_description TEXT,
    irn_no TEXT,
    created_date DATE
);

ON CONFLICT (header_id) DO NOTHING;

DROP VIEW IF EXISTS nicsi_erp.bill_desk_list CASCADE;
CREATE TABLE IF NOT EXISTS nicsi_erp.bill_desk_list (
    header_id BIGINT PRIMARY KEY,
    project_id BIGINT,
    prj_mgr_id BIGINT,
    project_no TEXT,
    final_po_no TEXT,
