    vendor_id BIGINT,
    vendor_name TEXT,
    invoice_no BIGINT,
    invoice_date DATE,
    received_date DATE,
    invoice_amount BIGINT,
    invoice_num BIGINT,
    invoice_amount_bk BIGINT,
    amount_paid BIGINT,
    invoice_status BIGINT,
    objection_remarks TEXT,
    status TEXT,
    created_date DATE
