ON CONFLICT (header_id) DO NOTHING;

DROP VIEW IF EXISTS nicsi_erp.invoice_list CASCADE;
CREATE TABLE IF NOT EXISTS nicsi_erp.invoice_list (
    header_id BIGINT PRIMARY KEY,
    project_id BIGINT,
    project_no TEXT,
    prj_mgr_id BIGINT,
    managername TEXT,
    pono TEXT,
    vendor_id BIGINT,
    vendor_name TEXT,
    invoice_num BIGINT,
    invoice_date DATE,
    gl_date DATE,
    invoice_amount BIGINT,
    amount_paid BIGINT,
    unpaid BIGINT,
    pen_amt BIGINT,
    objection NUMERIC(20,2),
